const { sessionId } = msg.req || msg.payload;
if (!sessionId) {
  msg.payload = { error: 'sessionId required' };
  return msg;
}

const scoringEngine = global.get('scoringEngine');
const reportEngine = global.get('reportEngine');

// Calculate score
const scoreResult = scoringEngine.calculateScore(sessionId);
const savedScore = scoringEngine.saveScore(sessionId, scoreResult);

// Generate report
const report = reportEngine.generateReport(sessionId);
const savedReport = reportEngine.saveReport(sessionId, report);

msg.payload = {
  sessionId,
  score: {
    overall: scoreResult.score,
    riskLevel: scoreResult.riskLevel
  },
  report: {
    reportId: report.reportId,
    summary: report.summary
  },
  status: 'complete'
};
return msg;

const { score, report, sessionId } = msg.payload;

let message = '*Risk Assessment Complete*\n\n';
message += '*CoverScore:* ' + score.overall + '/100\n';
message += '*Risk Level:* ' + score.riskLevel + '\n\n';
message += '*Summary:*\n' + report.summary + '\n\n';
message += 'Reply with *REPORT* to get your full Risk Intelligence Report.';

msg.payload = {
  messaging_product: 'whatsapp',
  to: msg.req?.phone || msg.phone,
  type: 'text',
  text: { body: message }
};
return msg;

const stateEngine = global.get('stateEngine');
stateEngine.transition(msg.req?.sessionId || msg.payload.sessionId, 'COMPLETE');
msg.statusCode = 200;
return msg;
